CREATE TABLE pellet_stock_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,pellet_stock_id BIGINT UNSIGNED NOT NULL,movement_type ENUM('production_in','packaging_out','reversal') NOT NULL,quantity_kg DECIMAL(12,3) NOT NULL,stock_before_kg DECIMAL(12,3) NOT NULL,stock_after_kg DECIMAL(12,3) NOT NULL,reference_type VARCHAR(80) NOT NULL,reference_id BIGINT UNSIGNED NOT NULL,created_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_psm_effect(pellet_stock_id,movement_type,reference_type,reference_id),CONSTRAINT fk_psm_stock FOREIGN KEY(pellet_stock_id) REFERENCES pellet_stocks(id),CONSTRAINT fk_psm_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
